S = "Hakeem Force Academy"
QS = [
(S, "In which year did the first All Pakistan Educational Conference take place in Karachi?", ["1947", "1948", "1949", "1950"], 0,
 "The conference was held in Karachi from 27 November to 1 December 1947, just after independence. It was opened by Quaid-e-Azam's message on education policy.", "Its date is the 27th of November 1947 as the start of the conference.", [705, 248]),
(S, "The Babusar Pass connects the Kaghan Valley with which town?", ["Chilas", "Skardu", "Gilgit city", "Chitral"], 0,
 "The Babusar Pass links the Kaghan Valley in Khyber Pakhtunkhwa with Chilas in Gilgit-Baltistan. It is a high mountain pass open mainly in summer.", "The pass is about 4173 metres high.", [64]),
(S, "The Tochi Pass connects Pakistan with which country?", ["Afghanistan", "China", "Iran", "India"], 0,
 "The Tochi Pass lies in North Waziristan and leads into Afghanistan. China is reached through the Khunjerab Pass instead.", "The Tochi River flows through this pass.", [158, 850]),
(S, "The Shahrah-e-Resham (Silk Road, Karakoram Highway) connects Pakistan with which country?", ["China", "Afghanistan", "Iran", "India"], 0,
 "The Karakoram Highway runs from Hasan Abdal to the Khunjerab Pass and into Xinjiang, China. It follows part of the old Silk Road.", "It is called the highest paved international road in the world.", [849]),
(S, "In which year did Muhammad bin Qasim complete the conquest of Sindh by defeating Raja Dahir?", ["712 AD", "711 AD", "713 AD", "750 AD"], 0,
 "Muhammad bin Qasim landed at Debal in 711 AD and defeated Raja Dahir at Rawar in 712 AD. Sindh then came under Umayyad rule.", "Some books give 711 AD for the start of the invasion and 712 AD for the conquest.", [699]),
(S, "On which date did Makkah fall to the Muslims in the Conquest of Makkah (Fath Makkah)?", ["20 Ramadan, 8 AH", "10 Ramadan, 6 AH", "1 Shawwal, 8 AH", "17 Ramadan, 2 AH"], 0,
 "Most Pakistani textbooks give 20 Ramadan 8 AH (January 630 AD) for the conquest. The Prophet (PBUH) entered Makkah peacefully.", "Sources differ slightly, some give 10 or 17 Ramadan 8 AH.", [742]),
(S, "On what date did the Government of India Act 1919 (Montagu-Chelmsford Reforms) receive royal assent?", ["23 December 1919", "20 August 1917", "1 April 1937", "15 August 1947"], 0,
 "The Act got royal assent on 23 December 1919 and the reforms started in 1921. They introduced dyarchy in the provinces.", "The 20 August 1917 date is Montagu's announcement in the House of Commons.", [28]),
(S, "In which year did Quaid-e-Azam Muhammad Ali Jinnah join the Indian National Congress?", ["1906", "1913", "1885", "1920"], 0,
 "Jinnah joined the Congress in 1906 and attended its Calcutta session. He later joined the Muslim League in 1913.", "He is called the ambassador of Hindu-Muslim unity in this period.", [213]),
(S, "In which year did Quaid-e-Azam resign from the Indian National Congress?", ["1920", "1906", "1916", "1930"], 0,
 "Jinnah left the Congress in 1920 because he opposed Gandhi's Non-Cooperation Movement and mass methods. He had disagreed with Congress politics.", "He signed the Lucknow Pact in 1916 while in both parties.", [274]),
(S, "On which date did Pakistan come into being according to the Islamic calendar?", ["27 Ramadan 1366 AH", "14 Rajab 1366 AH", "1 Shawwal 1366 AH", "27 Rajab 1366 AH"], 0,
 "Pakistan was created on 14 August 1947, which was 27 Ramadan 1366 AH, a Friday. It was also the Night of Power (Laylat al-Qadr) in many accounts.", "The date 27 Rajab is Shab-e-Miraj, not Pakistan's birth.", [750]),
(S, "In which year did the United States begin military action in Afghanistan after the 9/11 attacks?", ["2001", "1979", "2003", "2011"], 0,
 "US-led forces started airstrikes in Afghanistan on 7 October 2001. This followed the 11 September 2001 attacks.", "US forces left Afghanistan in August 2021.", [1087]),
(S, "Which comes next in the series: 1Z, 3X, 5V, ?", ["7T", "7U", "6T", "9R"], 0,
 "Numbers go up by 2 (1, 3, 5, 7) and letters go back by 2 (Z, X, V, T). So the next term is 7T.", "Z is the 26th letter and T is the 20th.", [284]),
(S, "Which number comes next: 3, 6, 12, 24, ?", ["36", "48", "30", "42"], 1,
 "Each number is double the previous one: 3x2=6, 6x2=12, 12x2=24, so 24x2=48.", "This is a geometric series with common ratio 2.", [1271]),
(S, "Which number comes next: 80, 70, 62, 56, ?", ["52", "50", "54", "48"], 0,
 "The differences are -10, -8, -6, so the next difference is -4. Thus 56 - 4 = 52.", "The differences themselves form an arithmetic series.", [1273]),
(S, "Complete the series: 3/2, 6/4, 10/8, 15/16, ?", ["21/32", "20/32", "21/24", "22/32"], 0,
 "Numerators increase by 3, 4, 5, 6 (3, 6, 10, 15, 21). Denominators double (2, 4, 8, 16, 32). So the next term is 21/32.", "The numerators are triangular numbers.", [184]),
(S, "A helicopter covers 240 km using 50 gallons of fuel. How many gallons are needed for the next 400 km?", ["83 1/3 gallons", "80 gallons", "75 gallons", "90 gallons"], 0,
 "Fuel per km is 50/240 gallons. For 400 km: 400 x 50 / 240 = 83 1/3 gallons.", "This is a direct proportion question.", [593]),
(S, "Who is the Supreme Commander of all the armed forces of Pakistan?", ["The President", "The Prime Minister", "The Chief Justice", "The Chairman Joint Chiefs of Staff Committee"], 0,
 "Under the Constitution of Pakistan, the President is the Supreme Commander of the armed forces. The Prime Minister runs the government.", "The President appoints the service chiefs on the advice of the Prime Minister.", [1372]),
(S, "In which continent is the Sahara Desert located?", ["Africa", "Asia", "Australia", "South America"], 0,
 "The Sahara lies across North Africa. It is the largest hot desert in the world.", "It covers an area of about 9 million square kilometres.", [652]),
(S, "Which is the largest continent of the world by area?", ["Africa", "Asia", "North America", "Europe"], 1,
 "Asia is the largest continent, covering about 44.6 million square kilometres. It is also the most populated.", "Africa is the second largest continent.", [67, 1250]),
(S, "Which is the correct spelling of the word meaning a person who does something for pleasure and not as a job?", ["amature", "amateur", "amatuer", "ameteur"], 1,
 "The correct spelling is amateur. It comes from the French word for lover.", "The opposite word is professional.", [1240]),
(S, "What is the value of cot 90 degrees?", ["0", "1", "Infinity", "-1"], 0,
 "cot 90 = cos 90 / sin 90 = 0 / 1 = 0.", "cot 0 degrees is undefined.", [883, 884]),
(S, "Where is the headquarters of the United Nations Security Council located?", ["Geneva", "New York", "Paris", "Vienna"], 1,
 "The Security Council is an organ of the United Nations, whose headquarters are in New York, USA. It meets there.", "The UN also has major offices in Geneva and Vienna.", [1160]),
(S, "What is the total number of members of the UN Security Council?", ["15", "10", "5", "20"], 0,
 "There are 5 permanent members and 10 non-permanent members, so 5 + 10 = 15.", "Non-permanent members are elected for two years.", [263]),
(S, "In which part of Pakistan is K2 located?", ["Gilgit-Baltistan", "Khyber Pakhtunkhwa", "Azad Kashmir", "Balochistan"], 0,
 "K2 is in the Karakoram range in Gilgit-Baltistan, on the border with China. It is 8611 metres high.", "K2 is the second highest peak in the world.", [654]),
(S, "Qantas is the national airline of which country?", ["Australia", "Austria", "Canada", "New Zealand"], 0,
 "Qantas is the flag carrier of Australia. The name comes from Queensland and Northern Territory Aerial Services.", "It was founded in 1920.", [63]),
(S, "Which country won the first FIFA Football World Cup in 1930?", ["Uruguay", "Argentina", "Brazil", "Italy"], 0,
 "Uruguay hosted the first World Cup in 1930 and beat Argentina 4-2 in the final.", "Italy won the next two tournaments in 1934 and 1938.", [1219]),
(S, "The rouble is the currency of which country?", ["Russia", "Poland", "Ukraine", "Bulgaria"], 0,
 "The rouble is the official currency of Russia. One rouble has 100 kopeks.", "Belarus also uses a rouble of its own.", [227, 2, 1016]),
(S, "What is the currency of North Korea?", ["Won", "Yuan", "Yen", "Ringgit"], 0,
 "North Korea uses the North Korean won. South Korea uses the South Korean won.", "Its capital is Pyongyang.", [938]),
(S, "In which year did Pakistan adopt its current Constitution?", ["1973", "1956", "1962", "1985"], 0,
 "The present Constitution was passed by the National Assembly and came into force in 1973. It replaced the 1962 Constitution.", "It was adopted on 10 April 1973 and enforced on 14 August 1973.", [1095]),
(S, "Change into passive voice: I take exercise daily.", ["Exercise is taken by me daily.", "Exercise was taken by me daily.", "Exercise is being taken by me daily.", "Exercise has been taken by me daily."], 0,
 "The sentence is in the simple present, so the passive uses is or are plus the past participle. So it becomes Exercise is taken by me daily.", "The object of the active sentence becomes the subject of the passive.", [472]),
(S, "The Darling is a famous what, located in Australia?", ["River", "Mountain", "Desert", "Lake"], 0,
 "The Darling is a river in Australia that joins the Murray River. It is about 1,500 km long.", "The Murray-Darling basin is Australia's main river system.", [502]),
(S, "A is the father of B, but B is not a daughter. What is B to A?", ["Son", "Brother", "Nephew", "Uncle"], 0,
 "B is a child of A and is not a daughter, so B is a son.", "The relation of A to B is father.", [406]),
(S, "Who wrote the book Daughter of Destiny?", ["Benazir Bhutto", "Fatima Jinnah", "Zulfikar Ali Bhutto", "Begum Nusrat Bhutto"], 0,
 "Daughter of Destiny is the autobiography of Benazir Bhutto, published in 1989. It was later reissued as Daughter of the East.", "Benazir Bhutto was the first woman Prime Minister of Pakistan.", [1442]),
(S, "Who founded the English newspaper Dawn?", ["Quaid-e-Azam Muhammad Ali Jinnah", "Liaquat Ali Khan", "Allama Iqbal", "Sir Syed Ahmad Khan"], 0,
 "Quaid-e-Azam founded Dawn in Delhi in 1941 as a voice of the Muslim League. It later moved to Karachi.", "Dawn started as a weekly and became a daily in 1942.", [1331, 1410]),
(S, "Between which two countries was the Tashkent Declaration signed in 1966?", ["India and Pakistan", "Pakistan and China", "India and China", "Pakistan and Afghanistan"], 0,
 "It ended the 1965 war between India and Pakistan. The Soviet Union mediated it.", "It was signed in January 1966.", [460]),
(S, "Who was the Commander-in-Chief of the Pakistan Army during the 1965 war?", ["General Muhammad Musa Khan", "General Ayub Khan", "General Yahya Khan", "General Tikka Khan"], 0,
 "General Muhammad Musa Khan was army chief from 1958 to 1966. Ayub Khan was President.", "Yahya Khan took over as army chief in 1966.", [393]),
(S, "Who was the first woman Chief Minister of a province of Pakistan?", ["Maryam Nawaz", "Benazir Bhutto", "Sherry Rehman", "Fehmida Mirza"], 0,
 "Maryam Nawaz became Chief Minister of Punjab in February 2024, the first woman to hold the post in any province. She belongs to PML-N.", "Benazir Bhutto was the first woman Prime Minister.", [1403]),
(S, "What is the boundary line between India and China commonly called?", ["Line of Actual Control", "Durand Line", "Radcliffe Line", "Line of Control"], 0,
 "The Line of Actual Control (LAC) is the de facto border between India and China. The McMahon Line is the eastern sector boundary drawn in 1914.", "Line of Control is between India and Pakistan in Kashmir.", [365, 29, 992]),
(S, "Which is the largest river of China?", ["Yangtze", "Yellow River", "Mekong", "Pearl River"], 0,
 "The Yangtze is about 6,300 km long and is the longest river in China and Asia. The Yellow River is second.", "It flows into the East China Sea near Shanghai.", [972]),
(S, "Lyallpur is the old name of which Pakistani city?", ["Faisalabad", "Sargodha", "Multan", "Sahiwal"], 0,
 "Lyallpur was renamed Faisalabad in 1979 in honour of King Faisal of Saudi Arabia. It was named after Sir James Lyall.", "Faisalabad is famous for textiles.", [732]),
(S, "The city of Savannah is located in which country?", ["USA", "Spain", "Australia", "Brazil"], 0,
 "Savannah is a historic port city in Georgia, United States. It lies on the Savannah River.", "A savannah is also a type of grassland.", [782]),
(S, "A train travels at 90 km/h and a car goes twice as fast as the train. How many km does the car cover in 30 minutes?", ["90 km", "45 km", "180 km", "60 km"], 0,
 "The car speed is 2 x 90 = 180 km/h. In half an hour it covers 180 x 0.5 = 90 km.", "Distance equals speed times time.", [418]),
]
